<?php
session_start(); require_once __DIR__.'/../config/config.php'; require_once __DIR__.'/../config/book_merchandising.php';
$requested=$_GET['type']??($_GET['tab']??'new'); $type=in_array($requested,['used','exchange'],true)?$requested:'new';
if($type==='exchange'){header('Location: /pages/exchange_books.php');exit;}
$section=($_GET['section']??'latest')==='best'?'best':'latest'; $isUsed=$type==='used';
$keyword=trim($_GET['q']??'');$condition=trim($_GET['condition']??'');$sellerType=trim($_GET['seller_type']??'');$category=trim($_GET['category']??'');$publisher=trim($_GET['publisher']??'');$author=trim($_GET['author']??'');$maxPrice=is_numeric($_GET['price']??null)?(float)$_GET['price']:0;$minRating=is_numeric($_GET['rating']??null)?(int)$_GET['rating']:0;$sort=$_GET['sort']??($section==='best'?'best':'latest');
$buyerLat=(float)($_COOKIE['buyer_lat']??0);$buyerLng=(float)($_COOKIE['buyer_lng']??0);if(empty($buyerLat)&&!empty($_SESSION['user_id'])){$userLoc=$pdo->prepare('SELECT latitude,longitude FROM users WHERE user_id=?');$userLoc->execute([$_SESSION['user_id']]);$u=$userLoc->fetch(PDO::FETCH_ASSOC);if($u&&$u['latitude']){$buyerLat=(float)$u['latitude'];$buyerLng=(float)$u['longitude'];}}$hasLocation=($buyerLat!=0&&$buyerLng!=0);
$page=max(1,(int)($_GET['page']??1));$perPage=12;$offset=($page-1)*$perPage;
$where=["b.status='available'",$isUsed?"b.book_type='used' AND b.condition_level<>'new'":"(b.book_type='new' OR b.condition_level='new')"];$params=[];
if($keyword!==''){$where[]='(b.title LIKE :kw OR b.author LIKE :kw OR b.isbn LIKE :kw OR b.isbn_13 LIKE :kw)';$params[':kw']="%$keyword%";}if($isUsed&&in_array($condition,['good','fair','old'],true)){$where[]='b.condition_level=:cond';$params[':cond']=$condition;}if($isUsed&&in_array($sellerType,['shop','publisher','user'],true)){$where[]='b.seller_type=:seller';$params[':seller']=$sellerType;}if($category!==''){$where[]='b.category=:category';$params[':category']=$category;}if(!$isUsed&&$publisher!==''){$where[]="COALESCE(NULLIF(b.publisher_name,''),p.company_name,s.shop_name)=:publisher";$params[':publisher']=$publisher;}if(!$isUsed&&$author!==''){$where[]='b.author=:author';$params[':author']=$author;}if($maxPrice>0){$where[]='b.price<=:price';$params[':price']=$maxPrice;}if($minRating>0){$where[]='COALESCE((SELECT AVG(fr.rating) FROM book_reviews fr WHERE fr.book_id=b.book_id),0)>=:rating';$params[':rating']=$minRating;}$whereSql=implode(' AND ',$where);
$orderSql=match($sort){'distance'=>($hasLocation?'distance ASC,b.created_at DESC':'b.created_at DESC'),'oldest'=>'b.created_at ASC','price_low'=>'b.price ASC','price_high'=>'b.price DESC','title'=>'b.title ASC','best'=>'sold_count DESC,b.book_id DESC',default=>'b.created_at DESC,b.book_id DESC'};
$count=$pdo->prepare("SELECT COUNT(*) FROM books b LEFT JOIN publishers p ON b.seller_type='publisher' AND p.publisher_id=b.seller_id LEFT JOIN shops s ON b.seller_type='shop' AND s.shop_id=b.seller_id WHERE $whereSql");$count->execute($params);$total=(int)$count->fetchColumn();$totalPages=max(1,(int)ceil($total/$perPage));
$distanceSql=$hasLocation?", (6371 * acos(cos(radians(:buyerLat)) * cos(radians(COALESCE(s.latitude,u.latitude))) * cos(radians(COALESCE(s.longitude,u.longitude)) - radians(:buyerLng)) + sin(radians(:buyerLat)) * sin(radians(COALESCE(s.latitude,u.latitude))))) AS distance":", NULL AS distance";
$stmt=$pdo->prepare("SELECT b.*,COALESCE((SELECT SUM(oi.quantity) FROM order_items oi JOIN orders o ON o.order_id=oi.order_id WHERE oi.book_id=b.book_id AND o.payment_status NOT IN('cancelled','failed')),0) sold_count $distanceSql FROM books b LEFT JOIN publishers p ON b.seller_type='publisher' AND p.publisher_id=b.seller_id LEFT JOIN shops s ON b.seller_type='shop' AND s.shop_id=b.seller_id LEFT JOIN users u ON b.seller_type='user' AND u.user_id=b.seller_id WHERE $whereSql ORDER BY $orderSql LIMIT :lim OFFSET :off");foreach($params as $k=>$v)$stmt->bindValue($k,$v);if($hasLocation){$stmt->bindValue(':buyerLat',$buyerLat);$stmt->bindValue(':buyerLng',$buyerLng);}$stmt->bindValue(':lim',$perPage,PDO::PARAM_INT);$stmt->bindValue(':off',$offset,PDO::PARAM_INT);$stmt->execute();$books=wanawanAnnotateBooks($pdo,$stmt->fetchAll(PDO::FETCH_ASSOC));
$categories=$pdo->query("SELECT DISTINCT category FROM books WHERE status='available' AND category IS NOT NULL AND category<>'' ORDER BY category")->fetchAll(PDO::FETCH_COLUMN);$publishers=$pdo->query("SELECT DISTINCT COALESCE(NULLIF(b.publisher_name,''),p.company_name,s.shop_name) n FROM books b LEFT JOIN publishers p ON b.seller_type='publisher' AND p.publisher_id=b.seller_id LEFT JOIN shops s ON b.seller_type='shop' AND s.shop_id=b.seller_id WHERE b.status='available' AND COALESCE(NULLIF(b.publisher_name,''),p.company_name,s.shop_name) IS NOT NULL ORDER BY n")->fetchAll(PDO::FETCH_COLUMN);
$hasFilters=$keyword!==''||$condition!==''||$sellerType!==''||$category!==''||$publisher!==''||$author!==''||$maxPrice>0||$minRating>0;$title=$hasFilters?'ผลการกรองหนังสือ':($isUsed?'คลังหนังสือมือสอง':($section==='best'?'หนังสือขายดี':'หนังสือมาใหม่ล่าสุด'));$active_zone=$isUsed?'used':'new';$breadcrumbs=[['label'=>'หน้าหลัก','url'=>'/pages/home.php'],['label'=>$isUsed?'ตามหาเล่มโปรด':'เลือกซื้อเล่มใหม่','url'=>$isUsed?'/pages/used_books.php':'/pages/new_books.php'],['label'=>$title,'url'=>'']];
function cImg(?string $v):?string{if(!$v)return null;if(preg_match('#^https?://#i',$v))return $v;$v=ltrim(str_replace('\\','/',$v),'/');return str_starts_with($v,'uploads/')?'/pages/'.$v:'/assets/image/books/'.$v;}function cQuery(array $c=[]):string{$q=array_merge($_GET,$c);return '?'.http_build_query(array_filter($q,fn($v)=>$v!==''&&$v!==null));}
?>
<!DOCTYPE html><html lang="th"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=$title?> - วนวรรณ</title><link rel="stylesheet" href="../assets/css/styles.css"><style>
*{box-sizing:border-box}.wrap{max-width:1200px;margin:auto;padding:32px 40px 80px}.title{display:flex;align-items:center;gap:14px;color:var(--secondary-color);font-size:36px;margin:0 0 25px}.title svg{width:42px;height:42px}.filters{border:1px solid #d8ddd4;border-radius:14px;padding:20px 24px;background:#fff;box-shadow:0 3px 8px #00000012}.filter-grid{display:grid;grid-template-columns:1.7fr repeat(4,1fr);gap:14px}.field label{display:block;color:var(--secondary-color);font-size:var(--text-sm);font-weight:600;margin-bottom:6px}.field input,.field select{width:100%;height:40px;border:1px solid var(--border-color);border-radius:8px;padding:0 11px;font-family:var(--font-family)}.actions{display:flex;justify-content:flex-end;gap:10px;margin-top:14px}.btn{min-width:110px;height:38px;border:1px solid #d3948b;border-radius:8px;font-family:var(--font-family);display:grid;place-items:center;text-decoration:none;cursor:pointer}.submit{background:#d3948b;color:#fff}.reset{background:#fff;color:#d3948b}.results{display:flex;justify-content:space-between;align-items:center;border:1px solid #d8ddd4;border-radius:12px;padding:15px 26px;margin:34px 0;color:var(--secondary-color);font-weight:600;box-shadow:0 2px 6px #00000010}.sort{display:flex;align-items:center;gap:10px}.sort select{height:38px;border:1px solid #d8ddd4;border-radius:8px;padding:0 10px;font-family:var(--font-family)}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:20px}.empty{grid-column:1/-1;text-align:center;padding:80px;color:var(--text-muted)}.pagination{display:flex;justify-content:center;gap:10px;margin-top:48px}.pagination a{width:44px;height:44px;border:1px solid var(--secondary-color);border-radius:8px;display:grid;place-items:center;text-decoration:none;color:var(--secondary-color);font-weight:600}.pagination .active{background:var(--secondary-color);color:#fff}@media(max-width:1000px){.filter-grid,.grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.wrap{padding:24px 18px 60px}.filter-grid,.grid{grid-template-columns:1fr}.results{align-items:flex-start;flex-direction:column;gap:12px}.title{font-size:28px}}
</style></head><body><?php require __DIR__.'/../components/header.php';?><main class="wrap"><h1 class="title"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h6"/></svg><?=$title?></h1>
<form class="filters" method="get"><input type="hidden" name="type" value="<?=$type?>"><input type="hidden" name="section" value="<?=$section?>"><div class="filter-grid"><div class="field"><label>ค้นหาตามชื่อ/ผู้แต่ง</label><input name="q" value="<?=htmlspecialchars($keyword)?>" placeholder="พิมพ์ชื่อหนังสือที่คุณกำลังตามหา..."></div><?php if($isUsed):?><div class="field"><label>สภาพหนังสือ</label><select name="condition"><option value="">ทั้งหมด</option><?php foreach(['good'=>'สภาพดี','fair'=>'พอใช้','old'=>'หนังสือเก่า'] as $v=>$l):?><option value="<?=$v?>" <?=$condition===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select></div><div class="field"><label>ประเภทผู้ขาย</label><select name="seller_type"><option value="">ทั้งหมด</option><option value="shop" <?=$sellerType==='shop'?'selected':''?>>ร้านค้า</option><option value="publisher" <?=$sellerType==='publisher'?'selected':''?>>สำนักพิมพ์</option></select></div><?php else:?><div class="field"><label>สำนักพิมพ์</label><select name="publisher"><option value="">ทั้งหมด</option><?php foreach($publishers as $v):?><option <?=$publisher===$v?'selected':''?>><?=htmlspecialchars($v)?></option><?php endforeach;?></select></div><div class="field"><label>หมวดสินค้า</label><select disabled><option>มือหนึ่ง</option></select></div><?php endif;?><div class="field"><label>หมวดหมู่</label><select name="category"><option value="">ทั้งหมด</option><?php foreach($categories as $v):?><option <?=$category===$v?'selected':''?>><?=htmlspecialchars($v)?></option><?php endforeach;?></select></div><div class="field"><label>ราคาสูงสุด</label><select name="price"><option value="">ทั้งหมด</option><?php foreach([100,200,300,500,1000] as $v):?><option value="<?=$v?>" <?=$maxPrice==$v?'selected':''?>>ไม่เกิน ฿<?=$v?></option><?php endforeach;?></select></div></div><div class="actions"><button type="button" class="btn" style="background:#f4f4f4;color:#444;border-color:#ccc" onclick="setGPSCookie()">📍 ดึงพิกัดหาระยะทาง</button><button class="btn submit">กรองข้อมูล</button><a class="btn reset" href="/pages/catalog.php?type=<?=$type?>&section=<?=$section?>">ล้าง</a></div></form>
<div class="results"><span>แสดงผลลัพธ์ที่ <?=$total?($offset+1).'–'.min($offset+$perPage,$total):'0'?> จากทั้งหมด <?=number_format($total)?> รายการ</span><form class="sort"><input type="hidden" name="type" value="<?=$type?>"><input type="hidden" name="section" value="<?=$section?>"><label>จัดเรียงตาม:</label><select name="sort" onchange="this.form.submit()"><option value="latest" <?=$sort==='latest'?'selected':''?>>ใหม่ล่าสุด</option><?php if($hasLocation):?><option value="distance" <?=$sort==='distance'?'selected':''?>>ใกล้ฉันที่สุด</option><?php endif;?><option value="best" <?=$sort==='best'?'selected':''?>>ขายดี</option><option value="price_low" <?=$sort==='price_low'?'selected':''?>>ราคาต่ำสุด</option><option value="price_high" <?=$sort==='price_high'?'selected':''?>>ราคาสูงสุด</option><option value="title" <?=$sort==='title'?'selected':''?>>ชื่อหนังสือ</option></select></form></div>
<div class="grid"><?php if(!$books):?><p class="empty">ไม่พบหนังสือตามตัวกรอง</p><?php else:foreach($books as $r){$distanceText=$r['distance']!==null?number_format($r['distance'],1).' กม.':'';$book=['id'=>$r['book_id'],'title'=>$r['title'],'author'=>$r['author']??'','price'=>$r['price'],'badge'=>(string)($r['badge']??''),'image'=>cImg($r['image_cover']??null),'distance'=>$distanceText,'stock_quantity'=>$r['stock_quantity']??1];$card_type=$isUsed?'used':'new';require __DIR__.'/../components/book_card.php';}endif;?></div><?php if($totalPages>1):?><nav class="pagination"><?php for($p=1;$p<=$totalPages;$p++):?><a class="<?=$p===$page?'active':''?>" href="<?=htmlspecialchars(cQuery(['page'=>$p]))?>"><?=$p?></a><?php endfor;?></nav><?php endif;?></main><?php require __DIR__.'/../components/footer.php';?><script>function addToCart(id){alert('เพิ่มหนังสือลงรถเข็นแล้ว');}function setGPSCookie(){if(navigator.geolocation){navigator.geolocation.getCurrentPosition(p=>{document.cookie="buyer_lat="+p.coords.latitude+"; path=/; max-age=86400";document.cookie="buyer_lng="+p.coords.longitude+"; path=/; max-age=86400";location.reload();},()=>alert('ไม่สามารถดึงตำแหน่งได้'));}else{alert('ไม่รองรับการดึงตำแหน่ง');}}</script></body></html>
